-- Every listed agency, researched 2026-11-20: 229 catalog entries for the 46 agencies
-- that had none, from docs/sources/guam-permits-catalog.md sections 12 to 23.
-- Generated from lib/catalog.generated.json. None of these can be tracked yet.

on conflict (code) do nothing;

-- The lead agency is now the first one the label names as a whole word.
-- Land use forms lead with the Land Use Commission, seashore with the Seashore
-- Protection Commission, clearing with Guam EPA, burning permits with the Fire Department.
update public.permit_catalog set agency_code = 'gluc' where code = 'zone-change-gluc-form-02';
update public.permit_catalog set agency_code = 'gluc' where code = 'zone-variance-gluc-form-03';
update public.permit_catalog set agency_code = 'gluc' where code = 'conditional-use-gluc-form-01';
update public.permit_catalog set agency_code = 'gluc' where code = 'subdivision-variance-tentative-final-subdivision-forms-04-06';
update public.permit_catalog set agency_code = 'gluc' where code = 'tentative-development-plan-wetland-hpr-timeshare-forms-07-10';
update public.permit_catalog set agency_code = 'gspc' where code = 'seashore-clearance-gspc-form-01';
update public.permit_catalog set agency_code = 'gepa' where code = 'clearing-grubbing-grading-stockpiling';
update public.permit_catalog set agency_code = 'gfd' where code = 'burning-permit';
